WITH cols AS (SELECT table_name,md5(string_agg(column_name||':'||data_type||':'||udt_name||':'||is_nullable||':'||coalesce(column_default,'')||':'||coalesce(character_maximum_length::text,'')||':'||coalesce(numeric_precision::text,'')||':'||coalesce(numeric_scale::text,''),'|' ORDER BY ordinal_position)) AS columns_hash FROM information_schema.columns WHERE table_schema='public' AND table_name<>'_prisma_migrations' GROUP BY table_name), idx AS (SELECT tablename,md5(string_agg(indexdef,'|' ORDER BY indexname)) AS indexes_hash FROM pg_indexes WHERE schemaname='public' GROUP BY tablename), con AS (SELECT rel.relname,md5(string_agg(pg_get_constraintdef(c.oid),'|' ORDER BY c.conname)) AS constraints_hash FROM pg_constraint c JOIN pg_class rel ON c.conrelid=rel.oid JOIN pg_namespace n ON rel.relnamespace=n.oid WHERE n.nspname='public' AND c.contype<>'n' GROUP BY rel.relname) SELECT cols.*,idx.indexes_hash,con.constraints_hash FROM cols LEFT JOIN idx ON idx.tablename=cols.table_name LEFT JOIN con ON con.relname=cols.table_name ORDER BY cols.table_name
